#!/usr/bin/env python3
"""AIRTAXI_POWER1 analysis (registration planned/AIRTAXI_POWER1_PREREG.md). Reads out/airtaxi_power1_*.json; prints verdicts; writes planned/airtaxi_power1_results_table.md."""
import json, glob, statistics as st
rows = [r for f in sorted(glob.glob('out/airtaxi_power1_[0-9]*.json')) for r in json.load(open(f)) if not r.get('skipped')]
assert all(r['k1bad'] == 0 for r in rows), 'K1 failed in a study run'
def sel(net, m, T): return [r for r in rows if r['net'] == net and r['metro'] == m and r['T'] == T]
def busiest(r, e): sid = max(r['sites'], key=lambda s: r['sites'][s]['byE'][str(e)]['peakMW']); return sid, r['sites'][sid]['byE'][str(e)]
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
x = sel('7site', 'DFW', 24); lo = st.median(busiest(r, 0.45)[1]['peakMW'] for r in x); hi = st.median(busiest(r, 0.85)[1]['peakMW'] for r in x)
chk('P1', lo >= 0.3 and hi <= 1.2, f'7-site DFW 24/h busiest-site peak: {lo:.2f} MW (e 0.45) to {hi:.2f} MW (e 0.85), n={len(x)}')
x = sel('7site', 'DFW', 48); n = sum(1 for r in x if busiest(r, 0.85)[1]['peakMW'] > 0.9)
chk('P2', n >= 8, f'7-site DFW 48/h seeds with busiest site > 0.9 MW at e 0.85: {n} of {len(x)}')
a = [busiest(r, 0.65)[0] for r in sel('7site', 'DFW', 24)]; b = [busiest(r, 0.65)[0] for r in sel('7site', 'HOU', 12)]
chk('P3', a.count('DFWc') >= 7 and b.count('IAH') >= 7, f'busiest site DFW 24/h: {dict((k, a.count(k)) for k in sorted(set(a)))}; HOU 12/h: {dict((k, b.count(k)) for k in sorted(set(b)))}')
x = sel('archer', 'DFW', 48); v = st.median(busiest(r, 0.85)[1]['peakMW'] for r in x)
chk('P4', v >= 1.5, f'Archer DFW 48/h busiest-site peak at e 0.85: {v:.2f} MW (n={len(x)})')
x = sel('7site', 'DFW', 24); v = st.median(busiest(r, 0.65)[1]['MWh'] for r in x)
chk('P5', 1.5 <= v <= 6, f'7-site DFW 24/h busiest-site energy over 12 h at e 0.65: {v:.2f} MWh')
npass = sum(1 for _, ok, _ in P if ok); print(f'{npass} of {len(P)} passed')
L = ['# AIRTAXI_POWER1 results table (generated by planned/airtaxi_power1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(rows)}; K1 exact in all.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Busiest site per setup (median over seeds; range in brackets)', '', '| Network | Trips/h | Busiest site (seeds) | Peak aircraft charging | Peak MW at e 0.45 / 0.65 / 0.85 | MWh over 12 h at e 0.65 | Network MWh over 12 h at e 0.65 |', '|---|---|---|---|---|---|---|']
for net in ('7site', 'archer'):
    for m in ('DFW', 'HOU'):
        for T in sorted({r['T'] for r in rows if r['net'] == net and r['metro'] == m}):
            x = sel(net, m, T)
            if not x: continue
            ids = [busiest(r, 0.65)[0] for r in x]; top = max(set(ids), key=ids.count)
            pk = [max(s['peakCharging'] for s in r['sites'].values()) for r in x]
            mw = {e: [busiest(r, e)[1]['peakMW'] for r in x] for e in (0.45, 0.65, 0.85)}
            mwh = [busiest(r, 0.65)[1]['MWh'] for r in x]; net_mwh = [sum(s['byE']['0.65']['MWh'] for s in r['sites'].values()) for r in x]
            L.append(f"| {net} {m} | {T} | {top} ({ids.count(top)}/{len(x)}) | {st.median(pk):.1f} ({min(pk):.0f}-{max(pk):.0f}) | " + ' / '.join(f'{st.median(mw[e]):.2f}' for e in (0.45, 0.65, 0.85)) + f" ({min(mw[0.85]):.2f}-{max(mw[0.85]):.2f} at 0.85) | {st.median(mwh):.2f} | {st.median(net_mwh):.1f} |")
open('planned/airtaxi_power1_results_table.md', 'w').write('\n'.join(L) + '\n'); print('wrote planned/airtaxi_power1_results_table.md')
